/* PasserBy: local, fictional high-fidelity simulation. No network requests. */
const $=s=>document.querySelector(s);
const icons={near:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2"/>',chat:'<path d="M20 11a8 8 0 0 1-8 8H5l-3 3v-10a9 9 0 0 1 18-1Z"/><path d="M7 10h8m-8 4h5"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',back:'<path d="m14 5-7 7 7 7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',time:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4 10-10"/>',spark:'<path d="m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7Z"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const people=[{id:'maple',alias:'Maple',name:'Alex',color:'leaf',interests:['Photography','Coffee','Nature'],bio:'Always looking for a good coffee and a new photo spot. Up for a campus photo walk?',activity:'A photo walk after class'},{id:'sunny',alias:'Sunny',name:'Sam',color:'sun',interests:['Coffee','Study','Music'],bio:'Study sessions are better with company. Happy to swap playlists over a coffee.',activity:'A relaxed study session'},{id:'river',alias:'River',name:'Jordan',color:'sky',interests:['Gaming','Music','Study'],bio:'Taking a break between classes. Tell me your favourite game or your current repeat song.',activity:'A conversation between classes'},{id:'peach',alias:'Peach',name:'Taylor',color:'peach',interests:['Nature','Art','Photography'],bio:'Finding small creative moments around campus. Sketchbook and camera usually nearby.',activity:'A creative break outdoors'}];
const allInterests=['Photography','Coffee','Study','Music','Nature','Gaming','Art','Sport'];
let state={screen:'welcome',alias:'Clover',interests:['Photography','Coffee'],onboarded:false,visible:false,filter:'All',selected:null,conversations:{},blocked:[],reports:[],offset:0};
// State deliberately stays in memory. Refresh closes this demonstration session.
function avatar(p,size=''){return `<div class="avatar ${p.color||'leaf'} ${size}" aria-hidden="true"><svg viewBox="0 0 60 60"><path d="M12 24C12 10 48 10 48 24v10c0 19-36 19-36 0Z" fill="#fff9e9"/><circle cx="23" cy="29" r="2.2" fill="#294833"/><circle cx="37" cy="29" r="2.2" fill="#294833"/><path d="M24 38q6 5 12 0" stroke="#294833" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M29 16q-12-7-7-14 13 2 10 14m0-1q3-11 12-11 1 10-12 11" fill="#41694b"/></svg></div>`}
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const person=()=>people.find(p=>p.id===state.selected);
const now=()=>Date.now()+state.offset;
function conversation(id=state.selected){return state.conversations[id]}
function expired(c){return c&&c.expiresAt&&now()>=c.expiresAt}
function expire(){Object.values(state.conversations).forEach(c=>{if(expired(c)){c.status='expired';c.messages=[];c.reveal='none'}})}
function hours(c){return Math.max(0,Math.ceil((c.expiresAt-now())/3600000))}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function go(screen,id){state.screen=screen;if(id)state.selected=id;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
function tags(p){return p.interests.map(t=>`<span class="tag ${state.interests.includes(t)?'shared':''}">${esc(t)}</span>`).join('')}
function notice(text,type='lock',warning=false){return `<div class="notice ${warning?'warning':''}">${icon(type)}<span>${text}</span></div>`}
function demo(text,buttons){return `<div class="demo"><span class="eyebrow">SIMULATION CONTROLS</span><p>${text}</p><div class="stack">${buttons}</div></div>`}
function btn(text,action,cls=''){return `<button class="btn ${cls}" data-action="${action}">${text}</button>`}
function header(kicker,title,desc=''){return `<div class="topline"><span class="eyebrow">${kicker}</span><span class="pill">Prototype</span></div><h1>${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}`}
function render(){expire();let pending=Object.values(state.conversations).filter(c=>c.status==='pending').length;$('#navigation').innerHTML=state.onboarded?[['nearby','near','Discover'],['chats','chat','Chats'],['privacy','shield','Privacy']].map(([s,i,t])=>`<button class="nav ${state.screen===s||s==='chats'&&state.screen==='chat'?'active':''}" data-go="${s}" ${state.screen===s?'aria-current="page"':''}>${icon(i)}${t}${s==='chats'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join(''):'';
let html='';const p=person(),c=conversation();
if(state.screen==='welcome')html=`${header('A NEW WAY TO MEET','Good people.<br>Common ground.')}<p class="muted">Meet people around campus through the things you love. Reveal your identity only when you both feel ready.</p><div class="hero"><div class="hero-art"><div class="orb one">${avatar(people[0])}</div><div class="orb two">${avatar(people[1])}</div><div class="orb three">${avatar(people[2])}</div></div><p><strong>A shared interest is a good hello.</strong><br>No public photo. No pressure to reveal.</p></div><div class="feature">${icon('near')}<div><strong>Nearby, not pinpointed</strong><p>Discover a shared campus pool. No maps or exact distances.</p></div></div><div class="feature">${icon('shield')}<div><strong>You set the pace</strong><p>Accept a chat, stay anonymous, leave whenever you need.</p></div></div>${btn('Create my demo profile','start','wide')}<p class="footer-note">For adults 18+ · Fictional profiles · No sign-up required</p>`;
if(state.screen==='setup')html=`${header('YOUR DEMO PROFILE','Start with what<br>you love.')}<div class="progress"><span class="done"></span><span></span></div><p class="muted">Choose a nickname and at least two interests. You can change these later.</p><label for="alias">Anonymous nickname</label><input id="alias" maxlength="24" value="${esc(state.alias)}" autocomplete="off"><label>Your interests <span class="small">(choose 2 or more)</span></label><div class="filters">${allInterests.map(t=>`<button class="chip ${state.interests.includes(t)?'selected':''}" aria-pressed="${state.interests.includes(t)}" data-interest="${t}">${t}</button>`).join('')}</div><div class="error" id="setup-error" role="alert"></div>${notice('Your nickname and interests are visible. Your identity stays hidden.')}<label class="check"><input type="checkbox" id="adult"> I confirm I am 18 or older for this demo.</label>${btn('Continue','setup-next','wide')}`;
if(state.screen==='consent')html=`${header('YOUR CHOICE','Find your<br>campus people.')}<div class="progress"><span class="done"></span><span class="done"></span></div><div class="card soft"><h2>Burwood campus</h2><p class="muted">A simulated shared area. This prototype never requests your device location.</p></div><div class="feature">${icon('lock')}<div><strong>No precise location</strong><p>Other profiles cannot see your position, distance or direction.</p></div></div><div class="feature">${icon('time')}<div><strong>Connections have a time limit</strong><p>Leaving the shared area starts a 48-hour chat expiry timer.</p></div></div><label class="check"><input type="checkbox" id="discover-consent"> Show my nickname and interests in the demo campus pool.</label><div class="error" id="consent-error" role="alert"></div>${btn('Join the campus pool','join','wide')}${btn('Not now · stay hidden','skip','wide text')}`;
if(state.screen==='nearby')html=`${header('BURWOOD · DEMO CAMPUS','Find your people.','Start with an interest. See where it goes.')}<div class="row between"><span class="pill"><span class="dot"></span>${state.visible?'Discovery is on':'You are hidden'}</span>${btn(state.visible?'Pause':'Turn on','toggle-visible','secondary')}</div>${!state.visible?`<div class="empty">${avatar(people[0])}<h2>A little space is okay.</h2><p class="muted">You are hidden from discovery. Existing chats remain available.</p>${btn('Enable discovery','toggle-visible')}</div>`:`${notice('Shared campus only. No precise locations or distances.')}<div class="filters" aria-label="Filter by interest">${['All',...state.interests].map(t=>`<button class="chip ${state.filter===t?'selected':''}" data-filter="${esc(t)}" aria-pressed="${state.filter===t}">${esc(t)}</button>`).join('')}</div><div class="section-label"><h2>People with common ground</h2></div><div class="people">${people.filter(x=>!state.blocked.includes(x.id)&&x.interests.some(i=>state.interests.includes(i))&&(state.filter==='All'||x.interests.includes(state.filter))).map(x=>`<article class="card person"><div class="person-top">${avatar(x)}<div><h2>${x.alias}</h2><p class="small">${x.interests.filter(i=>state.interests.includes(i)).length} shared interests</p></div></div><div class="tags">${tags(x)}</div><button class="btn secondary wide" data-person="${x.id}">Meet ${x.alias} ${icon('spark')}</button></article>`).join('')||'<div class="card"><h2>No matches for now</h2><p class="muted">Try another interest in Privacy, or reset the demo to restore the fictional profiles.</p></div>'}</div>`}<p class="footer-note">People and activity are fictional. No live users.</p>`;
if(state.screen==='profile'&&p)html=`<button class="back" data-go="nearby">${icon('back')} Discover</button><div class="profile">${avatar(p,'large')}<h1>${p.alias}</h1><span class="pill">${icon('lock')} Identity hidden</span></div><div class="card"><h3>A little about me</h3><p class="muted">${p.bio}</p><div class="tags">${tags(p)}</div></div><div class="card soft"><span class="eyebrow">OPEN TO</span><p>${p.activity}</p></div>${notice('A chat only starts after the other person accepts.')} ${c&&c.status==='pending'?`${btn('Request sent · waiting','none','wide secondary')}${demo('Act as the fictional recipient to test both possible responses.',btn('Simulate acceptance','accept')+btn('Simulate decline','decline','secondary'))}${btn('Cancel request','cancel','wide text')}`:c&&c.status==='active'?btn('Open chat','open-chat','wide'):c&&c.status==='expired'?notice('This connection has expired. Reset the demo to replay it.','time',true):btn('Say hello · send request','request','wide')}${btn('Safety options','safety','wide text')}`;
if(state.screen==='chats'){const ids=Object.keys(state.conversations).filter(id=>!state.blocked.includes(id));html=`${header('YOUR CONNECTIONS','A hello can<br>go a long way.')}<p class="muted">Chat only with people you choose.</p>${ids.length?ids.map(id=>{const x=people.find(y=>y.id===id),v=conversation(id);return `<article class="card"><div class="person-top">${avatar(x)}<div><h2>${x.alias}</h2><p class="small">${v.status==='pending'?'Request awaiting acceptance':v.status==='expired'?'Expired · messages cleared':v.reveal==='mutual'?'Identity shared with mutual consent':'Anonymous chat'}</p></div></div><button class="btn secondary wide" style="margin-top:15px" data-open="${id}">${v.status==='pending'?'View request':'Open conversation'}</button></article>`}).join(''):`<div class="empty">${avatar(people[1])}<h2>Your next hello is nearby.</h2><p class="muted">Discover someone with shared interests and send a chat request.</p>${btn('Discover people','discover')}</div>`}`}
if(state.screen==='chat'&&p&&c){html=`<button class="back" data-go="chats">${icon('back')} Chats</button><div class="chat-heading" style="margin-top:15px">${avatar(p,'mini')}<div><h2>${c.reveal==='mutual'?p.name:p.alias}</h2><p class="small">${c.reveal==='mutual'?'Both agreed to reveal':'Anonymous connection'}</p></div><button class="btn text" style="margin-left:auto" data-action="safety" aria-label="Safety options">${icon('shield')}</button></div>${c.status==='expired'?`<div class="empty">${icon('time')}<h1>This chapter<br>has closed.</h1><p class="muted">48 hours passed after leaving the shared area. Messages and identity consent were cleared in this demo.</p>${btn('Back to discovery','discover')}</div>`:`${notice(c.expiresAt?`You left the shared area. Chat expires in ${hours(c)} hours.`:'You are in the same simulated campus area. A 48-hour timer starts when you leave.','time',!!c.expiresAt)}${c.reveal==='mutual'?`<div class="card soft"><h3>You both chose to reveal</h3><p class="small">${esc(state.alias)} shares the fictional name Casey. ${p.alias} shares ${p.name}. No contact details or location are shared.</p></div>`:c.reveal==='requested'?`${notice('You agreed to reveal. Waiting for the other person. Identity is still hidden.')}${demo('The second consent is separate from your request.',btn('Simulate other person agreeing','agree')+btn('Simulate other person declining','reveal-decline','secondary'))}${btn('Withdraw reveal request','withdraw','text wide')}`:`${btn(`${icon('lock')} Reveal identity together`,'reveal','secondary wide')}`}<div class="thread" aria-label="Chat messages">${c.messages.map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.text)}<small>${m.mine?'You':p.alias}${m.mine?'':' · simulated'}</small></div>`).join('')}</div><form id="message-form" class="composer"><label class="skip" for="message">Message</label><input id="message" maxlength="500" placeholder="Write a friendly hello…" autocomplete="off"><button class="btn" type="submit">Send</button></form>${demo('Test area departure and expiry without waiting. These controls are not part of the real product.',c.expiresAt?btn('Advance time by 48 hours','advance','secondary'):btn('Simulate leaving shared area','leave','secondary'))}`}`}
if(state.screen==='privacy')html=`${header('YOUR SPACE','You are in control.')}<div class="card"><div class="person-top">${avatar({color:'leaf'},'mini')}<div><h2>${esc(state.alias)}</h2><p class="small">Your anonymous demo profile</p></div></div><div class="tags">${state.interests.map(t=>`<span class="tag shared">${esc(t)}</span>`).join('')}</div>${btn('Edit interests','edit','secondary wide')}</div><div class="card"><div class="settings-row"><div><h3>Campus discovery</h3><p>${state.visible?'Visible to the fictional campus pool':'Paused · hidden from discovery'}</p></div>${btn(state.visible?'Pause':'Enable','toggle-visible','secondary')}</div></div><div class="card"><h3>What is shared?</h3><p class="muted">Nickname and chosen interests. First names only after both people agree. Never precise locations or contact details.</p></div><div class="card"><h3>Blocked profiles · ${state.blocked.length}</h3>${state.blocked.length?state.blocked.map(id=>`<div class="row between"><p class="muted">${people.find(p=>p.id===id).alias}</p><button class="button-link" data-unblock="${id}">Unblock</button></div>`).join(''):'<p class="muted">No blocked profiles.</p>'}<p class="small">Unblocking does not restore deleted chats.</p></div><div class="card"><h3>Demo report log · ${state.reports.length}</h3><p class="muted">${state.reports.length?'Recorded locally for this session. No report has been sent to a moderator.':'No reports recorded.'}</p>${state.reports.map(r=>`<p class="small">${esc(r.alias)} · ${esc(r.reason)}</p>`).join('')}</div>${notice('Nothing is uploaded or saved after refresh. This simulation is not secure messaging or a real moderation service.')} ${btn('Reset all demo data','reset','danger wide')}`;
$('#main').innerHTML=html;
}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;d.showModal()}
function close(){ $('#dialog').close() }
function request(){state.conversations[state.selected]={status:'pending',messages:[],reveal:'none',expiresAt:null};render();toast('Chat request sent in this simulation.')}
function action(a){const p=person(),c=conversation();switch(a){case 'start':go('setup');break;case 'setup-next':{const name=$('#alias').value.trim();if(name.length<2||state.interests.length<2||!$('#adult').checked){$('#setup-error').textContent='Enter a nickname, choose at least two interests and confirm you are 18+.';return}state.alias=name;go('consent');break}case 'join':if(!$('#discover-consent').checked){$('#consent-error').textContent='Choose whether to join, or select Not now.';return}state.visible=true;state.onboarded=true;go('nearby');break;case 'skip':state.visible=false;state.onboarded=true;go('nearby');break;case 'toggle-visible':if(state.visible){state.visible=false;render();toast('Discovery paused. Existing chats are unchanged.')}else modal('Join the campus pool?',`<p>Your nickname and interests will become visible in this fictional campus pool. No real location is accessed.</p><div class="stack">${btn('Enable discovery','enable')}${btn('Stay hidden','close','secondary')}</div>`);break;case 'enable':state.visible=true;close();render();break;case 'request':request();break;case 'accept':if(c?.status!=='pending')return;c.status='active';c.messages=[{mine:false,text:'Hey! Nice to meet someone with a shared interest. What do you enjoy most about it?'}];go('chat');break;case 'decline':case 'cancel':delete state.conversations[state.selected];go('nearby');toast(a==='decline'?'The fictional recipient declined. No chat was opened.':'Request cancelled.');break;case 'open-chat':go('chat');break;case 'discover':go('nearby');break;case 'reveal':if(c?.status!=='active')return;modal('Reveal only when ready',`<p>You will share the fictional first name <strong>Casey</strong>. ${p.alias} must separately agree before either name is shown.</p><p class="small">A shared identity cannot be unseen. No photo or contact information is shared in this version.</p><div class="stack">${btn('I agree · request reveal','reveal-confirm')}${btn('Keep chatting anonymously','close','secondary')}</div>`);break;case 'reveal-confirm':if(c?.status!=='active')return;c.reveal='requested';close();render();break;case 'agree':if(c?.reveal!=='requested'||c.status!=='active')return;c.reveal='mutual';render();toast('Both consents received. Fictional names are now shared.');break;case 'reveal-decline':case 'withdraw':if(c)c.reveal='none';render();toast('Identity remains hidden. You can keep chatting.');break;case 'leave':if(c?.status!=='active')return;c.expiresAt=now()+48*3600000;state.visible=false;render();toast('Area departure simulated. The 48-hour timer has started.');break;case 'advance':state.offset+=48*3600000;render();break;case 'safety':modal('Your comfort comes first',`<p>Manage your connection with ${p.alias}. You do not need to explain why you want to leave.</p><div class="stack">${btn('Report a concern','report','secondary')}${btn(`Block ${p.alias}`,'block','danger')}${btn('Return to conversation','close','text')}</div>`);break;case 'block':modal(`Block ${p.alias}?`,`<p>This removes their profile, ends the connection and clears messages in this session. They cannot contact you in the demo.</p><div class="stack">${btn('Confirm block','block-confirm','danger')}${btn('Cancel','close','secondary')}</div>`);break;case 'block-confirm':if(!state.blocked.includes(p.id))state.blocked.push(p.id);delete state.conversations[p.id];close();go('nearby');toast(`${p.alias} blocked. Conversation removed.`);break;case 'report':modal('Report a concern',`<p>This is a local demonstration. No report will be sent to a real moderator.</p><label for="reason">Reason</label><select id="reason"><option>Unwanted contact</option><option>Harassment or abuse</option><option>Unsafe content</option><option>Other concern</option></select><label class="check"><input type="checkbox" id="report-block" checked> Also block this profile</label><div class="stack">${btn('Record demo report','report-confirm')}${btn('Cancel','close','secondary')}</div>`);break;case 'report-confirm':state.reports.push({alias:p.alias,reason:$('#reason').value});if($('#report-block').checked){state.blocked.push(p.id);delete state.conversations[p.id]}close();go('privacy');toast('Demo report recorded locally. Nothing was sent.');break;case 'edit':modal('Choose your interests',`<p>Select at least two. Changes update discovery immediately.</p><div class="filters">${allInterests.map(t=>`<button class="chip ${state.interests.includes(t)?'selected':''}" data-edit-interest="${t}" aria-pressed="${state.interests.includes(t)}">${t}</button>`).join('')}</div><p id="edit-error" class="error" role="alert"></p>${btn('Done','edit-done','wide')}`);break;case 'edit-done':if(state.interests.length<2){$('#edit-error').textContent='Choose at least two interests.';return}state.filter='All';close();render();break;case 'reset':modal('Reset this demo?',`<p>This clears messages, reports, blocked profiles and your demo preferences. Nothing outside this page is affected.</p><div class="stack">${btn('Reset demo','reset-confirm','danger')}${btn('Cancel','close','secondary')}</div>`);break;case 'reset-confirm':close();location.reload();break;case 'close':close();break;}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();go(state.onboarded?'nearby':'welcome');return}if(b.dataset.go)go(b.dataset.go);if(b.dataset.action)action(b.dataset.action);if(b.dataset.person)go('profile',b.dataset.person);if(b.dataset.open)go(conversation(b.dataset.open).status==='pending'?'profile':'chat',b.dataset.open);if(b.dataset.filter){state.filter=b.dataset.filter;render()}if(b.dataset.interest){state.alias=$('#alias').value;const adult=$('#adult').checked;toggleInterest(b.dataset.interest);render();$('#adult').checked=adult;document.querySelector(`[data-interest="${b.dataset.interest}"]`).focus()}if(b.dataset.editInterest){toggleInterest(b.dataset.editInterest);b.classList.toggle('selected');b.setAttribute('aria-pressed',state.interests.includes(b.dataset.editInterest))}if(b.dataset.unblock){state.blocked=state.blocked.filter(x=>x!==b.dataset.unblock);render();toast('Profile unblocked. Old conversations stay deleted.')}});
function toggleInterest(t){state.interests=state.interests.includes(t)?state.interests.filter(i=>i!==t):[...state.interests,t]}
// Treat interest editing as a transaction. Escape/cancel restores the original set.
let interestBackup=null;
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]')?.dataset.action;
 if(a==='edit') interestBackup=[...state.interests];
 if(a==='edit-done'&&state.interests.length>=2) interestBackup=null;
},true);
$('#dialog').addEventListener('close',()=>{
 if(interestBackup){state.interests=interestBackup;interestBackup=null;render()}
});
$('#dialog').addEventListener('keydown',e=>{
 if(e.key!=='Tab')return;
 const items=[...$('#dialog').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')].filter(el=>el.getClientRects().length);
 const first=items[0],last=items[items.length-1];
 if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}
 else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}
});
document.addEventListener('submit',e=>{if(e.target.id!=='message-form')return;e.preventDefault();expire();const c=conversation(),input=$('#message'),text=input.value.trim();if(!text||c?.status!=='active')return;c.messages.push({mine:true,text:text.slice(0,500)},{mine:false,text:'Thanks for sharing! This reply is simulated for the prototype.'});render();$('#message').focus()});
// Keep time-dependent guards correct even if the tab stays open for a long time.
setInterval(()=>{const before=JSON.stringify(state.conversations);expire();if(before!==JSON.stringify(state.conversations))render()},1000);
render();
